CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_sf_order_makassar`  AS SELECT `h`.`order_id` AS `order_id`, max(nullif(trim(`h`.`sf_code`),'')) AS `sf_code`, max(nullif(trim(`h`.`sf_name`),'')) AS `sf_name`, min(`h`.`io_ts`) AS `io_ts`, min(`h`.`re_ts`) AS `re_ts`, min(`h`.`ps_ts`) AS `ps_ts`, max(`h`.`sf_company_name`) AS `sf_company_name`, max(`h`.`sf_branch_name`) AS `sf_branch_name`, max(`h`.`cluster`) AS `cluster`, max(`h`.`kec_adm`) AS `kec_adm`, max(`h`.`desa_adm`) AS `desa_adm`, count(0) AS `jumlah_baris_sumber`, max(case when ucase(trim(`h`.`process_state`)) = 'COMPLETED' then 1 else 0 end) AS `pernah_completed`, max(case when ucase(trim(`h`.`process_state`)) = 'FALLOUT' then 1 else 0 end) AS `pernah_fallout` FROM `sf_sales_history` AS `h` WHERE ucase(trim(`h`.`sf_branch_name`)) = 'MAKASSAR' AND `h`.`order_id` is not null AND trim(`h`.`order_id`) <> '' AND `h`.`sf_code` is not null AND trim(`h`.`sf_code`) <> '' AND exists(select 1 from `sf_master_telkomsel` `m` where ucase(trim(`m`.`kode_sf`)) = ucase(trim(`h`.`sf_code`)) limit 1) GROUP BY `h`.`order_id` HAVING count(distinct ucase(trim(`h`.`sf_code`))) = 1 ;

